import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    it = iter(data)
    N = next(it)

    p = [0] * (N + 1)
    children = [[] for _ in range(N + 1)]

    for i in range(2, N + 1):
        pi = next(it)
        p[i] = pi
        children[pi].append(i)

    Q = next(it)

    LOG = (N + 1).bit_length()
    up = [[0] * (N + 1) for _ in range(LOG)]

    for i in range(2, N + 1):
        up[0][i] = p[i]

    for j in range(1, LOG):
        prev = up[j - 1]
        curr = up[j]
        for i in range(1, N + 1):
            pi = prev[i]
            if pi:
                curr[i] = prev[pi]

    def kth_ancestor(v, k):
        j = 0
        while k:
            if k & 1:
                v = up[j][v]
                if v == 0:
                    return 0
            k >>= 1
            j += 1
        return v

    tin = [0] * (N + 1)
    tout = [0] * (N + 1)
    node_at = [0] * (N + 1)

    timer = 0
    stack = [(1, 0)]

    while stack:
        v, state = stack.pop()
        if state == 0:
            timer += 1
            tin[v] = timer
            node_at[timer] = v
            stack.append((v, 1))
            for c in reversed(children[v]):
                stack.append((c, 0))
        else:
            tout[v] = timer

    bit = [0] * (N + 2)

    def bit_add(i, delta):
        while i <= N:
            bit[i] += delta
            i += i & -i

    def bit_sum(i):
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s

    def bit_kth(k):
        idx = 0
        bitmask = 1 << (N.bit_length() - 1)
        while bitmask:
            nxt = idx + bitmask
            if nxt <= N and bit[nxt] < k:
                idx = nxt
                k -= bit[nxt]
            bitmask >>= 1
        return idx + 1

    out = []

    for _ in range(Q):
        typ = next(it)

        if typ == 1:
            v = next(it)
            k = next(it)

            idx = tin[v]
            cnt = bit_sum(idx)
            special = 0

            if cnt:
                a_tin = bit_kth(cnt)
                a = node_at[a_tin]
                if tout[a] >= idx and a != v:
                    special = a

            if special:
                ans = kth_ancestor(special, k - 1)
            else:
                ans = kth_ancestor(v, k)

            out.append(str(ans))

        else:
            v = next(it)
            idx = tin[v]

            cnt = bit_sum(idx)
            inside = False

            if cnt:
                a_tin = bit_kth(cnt)
                a = node_at[a_tin]
                if tout[a] >= idx:
                    inside = True

            if not inside:
                L = idx
                R = tout[v]

                while True:
                    cntL = bit_sum(L - 1)
                    cntR = bit_sum(R)
                    if cntR - cntL <= 0:
                        break
                    first_idx = bit_kth(cntL + 1)
                    bit_add(first_idx, -1)

                bit_add(L, 1)

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()
